<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>BLACKSPUR — Foundry Nine</title>
<style>
  /* Look plan: a foundry at dusk. Six colours only: shell, plate, edge, chalk, rust, amber. */
  :root {
    --shell: #0d0f11;
    --plate: #171a1e;
    --edge: #2a2f35;
    --chalk: #e8e4da;
    --rust: #8a4a32;
    --amber: #e9a13b;
