  * { box-sizing: border-box; }
  html, body {
    margin: 0; height: 100%; overflow: hidden;
    background: var(--shell); color: var(--chalk);
    font-family: var(--font-ui);
    -webkit-font-smoothing: antialiased;
  }
  #viewport { position: fixed; inset: 0; }
  #viewport canvas { display: block; width: 100%; height: 100%; }
  #hud { position: fixed; inset: 0; pointer-events: none; user-select: none; }

  /* crosshair */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 40px; height: 40px; transform: translate(-50%, -50%); }
  #crosshair .tick { position: absolute; background: var(--chalk); }
  #crosshair .tick.top    { left: 19px; top: 0; width: 2px; height: 8px; }
  #crosshair .tick.bottom { left: 19px; bottom: 0; width: 2px; height: 8px; }
  #crosshair .tick.left   { top: 19px; left: 0; height: 2px; width: 8px; }
  #crosshair .tick.right  { top: 19px; right: 0; height: 2px; width: 8px; }
  #crosshair .dot { position: absolute; left: 19px; top: 19px; width: 2px; height: 2px; background: var(--chalk); opacity: .7; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%,-50%); opacity: 0; }
  #hitmarker.on { opacity: 1; }
  #hitmarker .tick { position: absolute; background: var(--amber); }
  #hitmarker .tick.a { left: 10px; top: 0; width: 2px; height: 6px; transform: rotate(45deg); }
  #hitmarker .tick.b { left: 10px; bottom: 0; width: 2px; height: 6px; transform: rotate(45deg); }
  #hitmarker .tick.c { top: 10px; left: 0; height: 2px; width: 6px; transform: rotate(45deg); }
  #hitmarker .tick.d { top: 10px; right: 0; height: 2px; width: 6px; transform: rotate(45deg); }

  #damage { position: fixed; inset: 0; opacity: 0; background: radial-gradient(circle at 50% 50%, rgba(138,74,50,0) 45%, rgba(138,74,50,.55) 100%); }

  /* scoreline */
  #scoreline {
    position: fixed; left: 50%; top: 14px; transform: translateX(-50%);
    display: flex; align-items: stretch; gap: 0;
    background: color-mix(in srgb, var(--plate) 88%, transparent);
    border: 1px solid var(--edge); border-radius: 3px;
    font-family: var(--font-readout); font-size: 13px; letter-spacing: .04em;
  }
  #scoreline .side { padding: 6px 12px; display: flex; align-items: baseline; gap: 7px; }
  #scoreline .side .tag { font-size: 10px; letter-spacing: .16em; opacity: .6; }
  #scoreline .side.atk .num { color: var(--rust); font-size: 19px; }
