  #banner.on { opacity: 1; }
  #banner .head { font-size: 42px; letter-spacing: -.02em; font-weight: 500; }
  #banner .sub { font-size: 12px; letter-spacing: .22em; opacity: .6; margin-top: 6px; }
  #banner.atk .head { color: var(--rust); }
  #banner.def .head { color: var(--chalk); }

  /* buy menu */
  #buy { position: fixed; inset: 0; display: none; place-items: center; background: color-mix(in srgb, var(--shell) 78%, transparent); pointer-events: auto; }
