  #buy .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  #buy button { font: inherit; text-align: left; display: flex; justify-content: space-between; align-items: baseline; gap: 10px; padding: 8px 10px; background: transparent; border: 1px solid var(--edge); border-radius: 2px; color: var(--chalk); cursor: pointer; }
  #buy button:hover:not(:disabled) { border-color: var(--amber); }
  #buy button:disabled { opacity: .34; cursor: not-allowed; }
  #buy button .n { font-size: 13px; }
  #buy button .k { font-family: var(--font-readout); font-size: 12px; color: var(--amber); }
  #buy button .d { font-family: var(--font-readout); font-size: 10px; opacity: .45; display: block; margin-top: 2px; }
  #buy .foot { display: flex; justify-content: space-between; margin-top: 14px; font-family: var(--font-readout); font-size: 11px; opacity: .6; }

  /* start overlay */
  #start { position: fixed; inset: 0; display: grid; place-items: center; background: radial-gradient(circle at 50% 40%, #1a1d21 0%, var(--shell) 70%); }
  #start.off { display: none; }
  #start .sheet { width: min(520px, 92vw); padding: 0 4px; }
  #start .kicker { font-family: var(--font-readout); font-size: 11px; letter-spacing: .34em; color: var(--rust); margin-bottom: 10px; }
  #start h1 { margin: 0; font-size: 58px; line-height: .94; letter-spacing: -.035em; font-weight: 600; }
  #start h1 span { display: block; color: var(--rust); }
  #start .blurb { margin: 16px 0 0; font-size: 14px; line-height: 1.55; color: #a9a49a; max-width: 44ch; }
  #start .start-btn { margin-top: 22px; font: inherit; font-size: 14px; letter-spacing: .04em; padding: 11px 20px; border-radius: 2px; border: 1px solid var(--amber); background: var(--amber); color: #141518; cursor: pointer; font-weight: 500; }
  #start .start-btn:hover { background: var(--chalk); border-color: var(--chalk); }
  #start .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 6px 18px; font-family: var(--font-readout); font-size: 11px; color: #8d887f; }
  #start .keys kbd { display: inline-block; min-width: 20px; padding: 1px 5px; border: 1px solid var(--edge); border-radius: 2px; color: var(--chalk); text-align: center; margin-right: 6px; }

  #flash { position: fixed; inset: 0; background: #fff; opacity: 0; pointer-events: none; }
  #vignette { position: fixed; inset: 0; background: radial-gradient(circle at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,.42) 100%); pointer-events: none; }
</style>
