      let prompt = '';
      if (p.alive) {
        const bomb = sim.bomb;
        if (bomb.state === 'carried' && bomb.carrier === p.id) {
          const site = MAP.sites.find((s) => Math.hypot(p.pos.x - s.x, p.pos.z - s.z) <= s.r);
          if (site) prompt = `HOLD E — PLANT ON ${site.name} (${Math.round((1 - bomb.plantProgress / MATCH.plantTime) * 100)}%)`;
