    const a = sim.actors[i];
    if (!a.alive) continue;
    if (a.team === TEAM.ATK || a.isPlayer) {
      g.fillStyle = a.isPlayer ? '#ffffff' : '#e07a4a';
    } else {
      const seen = a.id === p.lastDamage.from && sim.time - p.lastDamage.t < 1.4;
      if (!seen) continue;
      g.fillStyle = '#c9583a';
