    const x = (a.pos.x - minX) * sx;
    const z = (a.pos.z - minZ) * sz;
    g.beginPath();
    g.arc(x, z, a.isPlayer ? 4 : 3.2, 0, Math.PI * 2);
    g.fill();
  }

  if (sim.bomb.state === 'planted') {
    g.fillStyle = '#ff3b2f';
    g.beginPath();
    g.arc((sim.bomb.x - minX) * sx, (sim.bomb.z - minZ) * sz, 4, 0, Math.PI * 2);
    g.fill();
  }
